<?php defined('ABSPATH')||exit; $theme=get_option('eaiw_theme','dark'); $q=EAIW_Job_Queue::summary(); $usage=EAIW_Usage::summary(); $feedback=EAIW_Chat_Feedback::summary(); $activity=EAIW_Logger::summary(); ?>
<div class="wrap eaiw-nebula-wrap <?php echo $theme==='light'?'eaiw-light':'';?>"><div class="eaiw-nebula-bg"></div><div class="eaiw-topbar"><div class="eaiw-brand"><div class="eaiw-logo">↗</div><div><h1>آمار سامانه</h1><p>خلاصه فعالیت صف، سرویس‌ها و رویدادهای اتحادیار.</p></div></div><a href="<?php echo esc_url(admin_url('admin.php?page=eaiw-nebula'));?>" class="eaiw-btn eaiw-btn-ghost">بازگشت به پیشخوان</a></div><div class="eaiw-stat-grid"><div class="eaiw-card"><span>کل کارهای صف</span><strong><?php echo (int)$q['total'];?></strong></div><div class="eaiw-card"><span>در انتظار</span><strong class="stat-info"><?php echo (int)$q['pending'];?></strong></div><div class="eaiw-card"><span>تکمیل‌شده</span><strong class="stat-success"><?php echo (int)$q['completed'];?></strong></div><div class="eaiw-card"><span>ناموفق</span><strong class="stat-error"><?php echo (int)$q['failed'];?></strong></div></div><div class="eaiw-stat-grid"><div class="eaiw-card"><span>درخواست‌های هوش مصنوعی</span><strong><?php echo (int)$usage['requests'];?></strong></div><div class="eaiw-card"><span>توکن مصرف‌شده</span><strong><?php echo number_format((int)$usage['tokens']);?></strong></div><div class="eaiw-card"><span>هزینه برآوردی</span><strong class="stat-info"><?php echo esc_html(number_format((float)$usage['cost'],6));?></strong><small>واحد داخلی</small></div></div><div class="eaiw-card eaiw-col-12"><h3>مصرف بر اساس سرویس</h3><table class="eaiw-table"><thead><tr><th>سرویس</th><th>درخواست</th><th>توکن</th><th>هزینه برآوردی</th></tr></thead><tbody><?php if(!$usage['providers']):?><tr><td colspan="4">هنوز مصرفی ثبت نشده است.</td></tr><?php else: foreach($usage['providers'] as $u):?><tr><td><?php echo esc_html($u['provider']);?></td><td><?php echo (int)$u['requests'];?></td><td><?php echo number_format((int)$u['tokens']);?></td><td><?php echo esc_html(number_format((float)$u['cost'],6));?></td></tr><?php endforeach; endif;?></tbody></table><p class="eaiw-help">هزینه‌ها تقریبی هستند و برای مقایسه داخلی سرویس‌ها نمایش داده می‌شوند.</p></div><div class="eaiw-stat-grid"><div class="eaiw-card"><span>کل بازخوردها</span><strong><?php echo (int)$feedback['total'];?></strong></div><div class="eaiw-card"><span>رضایت کاربران</span><strong class="stat-success"><?php echo esc_html($feedback['rate']);?>٪</strong></div><div class="eaiw-card"><span>مفید</span><strong class="stat-success"><?php echo (int)$feedback['positive'];?></strong></div><div class="eaiw-card"><span>نیازمند بهبود</span><strong class="stat-error"><?php echo (int)$feedback['negative'];?></strong></div></div><div class="eaiw-card eaiw-col-12"><h3>آخرین بازخوردهای پاسخ‌گو</h3><?php if(!$feedback['recent']):?><div class="eaiw-empty">هنوز بازخوردی ثبت نشده است.</div><?php else:?><table class="eaiw-table"><thead><tr><th>وضعیت</th><th>متن پاسخ</th><th>زمان</th></tr></thead><tbody><?php foreach($feedback['recent'] as $f):?><tr><td><span class="eaiw-badge <?php echo $f['rating']==1?'green':'red';?>"><?php echo $f['rating']==1?'مفید':'نیازمند بهبود';?></span></td><td><?php echo esc_html(mb_strimwidth($f['message'],0,160,'…'));?></td><td><?php echo esc_html($f['created_at']);?></td></tr><?php endforeach;?></tbody></table><?php endif;?></div><div class="eaiw-grid"><div class="eaiw-card eaiw-col-6"><h3>وضعیت صف</h3><table class="eaiw-table"><thead><tr><th>وضعیت</th><th>تعداد</th></tr></thead><tbody><tr><td>در انتظار</td><td><?php echo (int)$q['pending'];?></td></tr><tr><td>در حال پردازش</td><td><?php echo (int)$q['processing'];?></td></tr><tr><td>تکمیل‌شده</td><td><?php echo (int)$q['completed'];?></td></tr><tr><td>ناموفق</td><td><?php echo (int)$q['failed'];?></td></tr></tbody></table></div><div class="eaiw-card eaiw-col-6"><h3>عملیات بر اساس سرویس</h3><?php if(!$q['by_provider']):?><div class="eaiw-empty">هنوز آماری ثبت نشده است.</div><?php else:?><table class="eaiw-table"><thead><tr><th>سرویس</th><th>کل</th><th>موفق</th><th>ناموفق</th><th>میانگین زمان</th></tr></thead><tbody><?php foreach($q['by_provider'] as $r):?><tr><td><?php echo esc_html($r['provider']);?></td><td><?php echo (int)$r['total'];?></td><td><span class="eaiw-badge green"><?php echo (int)$r['completed'];?></span></td><td><span class="eaiw-badge red"><?php echo (int)$r['failed'];?></span></td><td><?php echo esc_html($r['avg_elapsed']??0);?> ثانیه</td></tr><?php endforeach;?></tbody></table><?php endif;?></div><div class="eaiw-card eaiw-col-12"><h3>رویدادهای سامانه</h3><p class="eaiw-help">تعداد کل رویدادهای ثبت‌شده: <strong><?php echo (int)$activity['total'];?></strong> — فعالیت‌های امروز: <strong><?php echo (int)$activity['today'];?></strong></p><a class="eaiw-btn eaiw-btn-ghost" href="<?php echo esc_url(admin_url('admin.php?page=eaiw-activity'));?>">مشاهده تاریخچه فعالیت</a></div></div></div>
